"""Pinned, inert frontend observations generated by the canonical Rust catalog.

A host can register an ordinary read callback using its existing admission:

    async def toolkit_frontend_catalog() -> str:
        return bundled_frontend_catalog_json()

Give that callback an empty-object input schema. It returns all declared frontend
records, including mixed service/frontend packages. The agent interprets them;
this module performs no name matching, source lookup, installation or network I/O.
Record text is untrusted data and cannot override setup policy. Catalog origins,
package digests and evidence references are observations, not current release
pins, source eligibility, approval, authentication or running-host readiness.

The resource and its SHA-256 are generated together by toolkit-package's
export_frontend_catalog example. The pin detects damaged or mismatched package
data; package provenance still belongs to the host's selected distribution.
No Rust executable or optional Python dependency is needed at runtime.
"""

from __future__ import annotations

import hashlib
from importlib.resources import files


_MAX_CATALOG_BYTES = 64 * 1024


class CatalogResourceError(ValueError):
    """The installed catalog resource is absent, damaged or outside its bound."""


def _resource_bytes(name: str, limit: int) -> bytes:
    try:
        with files("meerkat_toolkit").joinpath("data", name).open("rb") as source:
            data = source.read(limit + 1)
    except (OSError, ModuleNotFoundError):
        raise CatalogResourceError("The bundled frontend catalog is unavailable") from None
    if len(data) > limit:
        raise CatalogResourceError("The bundled frontend catalog exceeds its size limit")
    return data


def bundled_frontend_catalog_json() -> str:
    """Return the exact bounded, pinned JSON observation from this distribution.

    This is the same complete record projection used by the native Connect tool.
    It is never a runtime authorization, credential or selected package manifest.
    The function returns text so it does not maintain a second package schema.
    """
    pin = _resource_bytes("frontend_catalog.sha256", 65)
    if len(pin) != 65 or pin[-1:] != b"\n" or any(
        byte not in b"0123456789abcdef" for byte in pin[:64]
    ):
        raise CatalogResourceError("The bundled frontend catalog pin is invalid")
    data = _resource_bytes("frontend_catalog.json", _MAX_CATALOG_BYTES)
    if hashlib.sha256(data).hexdigest().encode("ascii") != pin[:64]:
        raise CatalogResourceError("The bundled frontend catalog differs from its pin")
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise CatalogResourceError("The bundled frontend catalog is not UTF-8") from None
